from dynamodb.entity.entity import Entity, EntityType


class TodoEntity(Entity):
    entity_type = EntityType.Todo

    def __init__(self, pk: str=None, sk: str= None, title: str = None, completed: bool= None):
        self.pk = pk
        self.sk = sk
        self.title = title
        self.completed = completed

    @staticmethod
    def from_dict(data: dict):
        return TodoEntity(
            pk=data.get('pk'),
            sk=data.get('sk'),
            title=data.get('title'),
            completed=data.get('completed', False)
        )

    def to_dict(self):
        return {
            "pk": self.pk,
            "sk": self.sk,
            "title": self.title,
            "completed": self.completed
        }
